<template><view class="screen"><view class="nav"><view class="muted">ZO COMMUNITY</view><view class="heading">{{labels[tab]}}</view><view class="muted">发现游戏，分享热爱</view></view>
<template v-if="tab==='home'"><view v-if="config.announcement?.enabled" class="card"><view class="title">{{config.announcement.title}}</view><RichPost :content="config.announcement.content_html"/></view><view class="shortcuts"><view @click="feature('ai')">✦ AI 搜索</view><view @click="feature('lottery')">♧ 神秘宝箱</view><view @click="feature('gamebox')">▣ 游戏盒子</view></view><view class="segments"><text :class="{selected:sort==='latest'}" @click="sort='latest';reset()">最新发布</text><text :class="{selected:sort==='hot'}" @click="sort='hot';reset()">今日热帖</text><text :class="{selected:sort==='digest'}" @click="sort='digest';reset()">精华推荐</text></view><button class="publish" @click="compose">＋ 发布帖子</button></template>
<view v-if="tab==='search'"><view class="search"><input v-model="keyword" placeholder="搜索帖子、作者、版块" confirm-type="search" @confirm="search"/><button @click="search">搜索</button></view><view class="segments"><text v-for="(name,key) in searchTypes" :key="key" :class="{selected:searchType===key}" @click="searchType=key;search()">{{name}}</text><text @click="feature('ai')">✦ AI</text></view><view v-if="!keyword" class="card"><view class="title">最近搜索</view><view class="history"><text v-for="h in history" :key="h" @click="keyword=h;search()">{{h}}</text></view><view class="muted" @click="clearHistory">清除历史</view></view></view>
<view v-if="error" class="error">{{error}}<button @click="reset">重新加载</button></view>
<view v-if="tab==='forum'"><view v-for="f in forums" :key="f.fid" :class="f.type==='group'?'section':'card'" @click="selectForum(f)"><view class="title">{{f.name}}</view><view v-if="f.type!=='group'" class="muted">{{f.threads}} 个主题 · 今日 {{f.todayposts}} 帖</view></view></view>
<view v-else-if="tab==='notify'"><view v-if="!account.token" class="card"><view class="title">登录查看消息</view><button @click="login">登录 / 注册</button></view><template v-else><view class="segments"><text v-for="(name,key) in notifyTypes" :key="key" :class="{selected:notifyType===key}" @click="notifyType=key;reset()">{{name}}</text></view><view class="muted" @click="clearRead">清理已读通知</view><view v-for="n in notices" :key="n.id||n.plid||n.touid" class="card" @click="notice(n)"><view class="title">{{n.author||n.tousername||n.lastauthor||'系统通知'}} <text v-if="!n.is_read&&notifyType!=='pm'" class="dot">●</text></view><view>{{n.lastsummary||n.message||''}}</view><RichPost v-if="n.content_html" :content="n.content_html"/></view><view v-if="!notices.length&&!busy" class="empty">暂无消息</view></template></view>
<view v-else-if="tab==='mine'"><view class="card"><template v-if="account.user"><image :src="account.user.avatar" class="avatar" @click="profile(account.user.uid)"/><view class="title">{{account.user.username}}</view><view class="muted">{{account.user.grouptitle}} · {{account.user.credits}} 积分 · {{account.user.oltime||0}} 小时</view><view class="stats">{{account.user.posts||0}} 帖子 · {{account.user.extcredits2||0}} 金币</view></template><template v-else><view class="title">加入 ZO 社区</view><view class="muted">登录后分享、收藏并参与讨论</view><button @click="login">登录 / 注册</button></template></view><view class="card"><view class="menu" @click="mineThreads">我的帖子 ›</view><view class="menu" @click="feature('favorites')">云端收藏 ›</view><view class="menu" @click="feature('medals')">勋章中心 ›</view><view class="menu" @click="settings">个人设置 / 手机绑定 ›</view><view class="menu" @click="openExternal('https://www.zozse.cn')">论坛官网 ›</view></view></view>
<view v-else><view v-if="fid" class="card"><view @click="clearForum">{{forumName}} · 返回全部帖子</view><button @click="compose">在此版块发帖</button></view><template v-if="tab==='search'&&searchType!=='thread'"><view class="card" v-for="r in threads" :key="r.uid||r.fid" @click="result(r)">{{r.username||r.name}} ›</view></template><template v-else><ThreadCard v-for="t in threads" :key="t.tid" :thread="t"/></template><view v-if="!threads.length&&!busy" class="empty">{{tab==='search'?'尝试游戏名称或其他关键词':'暂无内容，稍后再来看看'}}</view></view>
<view v-if="busy" class="empty">正在加载…</view><button v-if="hasMore&&!busy&&tab!=='mine'&&tab!=='forum'" @click="load">加载更多</button><view class="tabs"><view v-for="key in keys" :key="key" :class="['tab',{active:tab===key}]" @click="switchTab(key)"><view class="icon">{{icons[key]}}<text v-if="key==='notify'&&unread" class="badge">{{unread>99?'99+':unread}}</text></view>{{labels[key]}}</view></view></view></template>
<script setup>
import { ref } from 'vue'
import { onLoad,onShow,onPullDownRefresh,onReachBottom } from '@dcloudio/uni-app'
import { request,post,requireLogin } from '../../api/index.js'
import { useAccount } from '../../store/account.js'
import { openExternal } from '../../utils/openExternal.js'
import ThreadCard from '../../components/ThreadCard.vue'
import RichPost from '../../components/RichPost.vue'
const account=useAccount(),keys=['home','forum','search','notify','mine'],labels={home:'首页',forum:'版块',search:'搜索',notify:'消息',mine:'我的'},icons={home:'⌂',forum:'▦',search:'⌕',notify:'♧',mine:'◎'},searchTypes={thread:'帖子',author:'作者',forum:'版块'},notifyTypes={system:'系统',notice:'互动',pm:'私信'}
const tab=ref('home'),threads=ref([]),forums=ref([]),keyword=ref(''),page=ref(1),busy=ref(false),error=ref(''),hasMore=ref(false),fid=ref(0),forumName=ref(''),sort=ref('latest'),config=ref({}),searchType=ref('thread'),notifyType=ref('notice'),notices=ref([]),unread=ref(0),history=ref(uni.getStorageSync('zo-search-history')||[]);let generation=0
async function load(){if(busy.value||tab.value==='mine'||(tab.value==='search'&&!keyword.value.trim())||(tab.value==='notify'&&!account.token))return;busy.value=true;error.value='';const ticket=generation;try{if(tab.value==='forum'){const d=await request('forum/list.php');if(ticket===generation)forums.value=d}else{const path=tab.value==='notify'?'notify/list.php':tab.value==='search'?'search/thread.php':fid.value?'forum/detail.php':'thread/latest.php';const d=await request(path,{page:page.value,keyword:keyword.value,fid:fid.value,sort:sort.value,type:tab.value==='notify'?notifyType.value:searchType.value});if(ticket!==generation)return;if(tab.value==='notify')notices.value.push(...d.list);else threads.value.push(...d.list);hasMore.value=page.value<(d.page?.total_page||0);page.value++}}catch(e){if(ticket===generation)error.value=e.message}finally{if(ticket===generation)busy.value=false;uni.stopPullDownRefresh()}}
function reset(){generation++;busy.value=false;threads.value=[];notices.value=[];page.value=1;hasMore.value=false;error.value='';load()}
function switchTab(key){tab.value=key;fid.value=0;reset()}
function clearHistory(){history.value=[];uni.removeStorageSync('zo-search-history')}
function search(){if(keyword.value.trim()){history.value=[keyword.value.trim(),...history.value.filter(h=>h!==keyword.value.trim())].slice(0,10);uni.setStorageSync('zo-search-history',history.value)}reset()}
function selectForum(f){if(f.type==='group')return;tab.value='home';fid.value=Number(f.fid);forumName.value=f.name;reset()}
function clearForum(){fid.value=0;reset()}
function login(){uni.navigateTo({url:'/pages/auth/index'})}
function profile(uid){uni.navigateTo({url:'/pages/profile/index?uid='+uid})}
function feature(kind){if(kind==='lottery'){uni.navigateTo({url:'/pages/lottery/index'});return}if(['lottery','favorites','medals'].includes(kind)&&!requireLogin())return;uni.navigateTo({url:'/pages/features/index?kind='+kind})}
function compose(){if(requireLogin())uni.navigateTo({url:'/pages/compose/index?fid='+fid.value})}
function settings(){if(requireLogin())uni.navigateTo({url:'/pages/settings/index'})}
function mineThreads(){if(requireLogin())profile(account.user.uid)}
function result(r){if(r.uid)profile(r.uid);else selectForum({fid:r.fid,name:r.name,type:'forum'})}
function link(e){if(!e.href?.startsWith('#'))openExternal(e.href)}
async function notice(n){if(notifyType.value==='pm'){const uid=n.touid||n.lastauthorid;if(uid)uni.navigateTo({url:'/pages/chat/index?uid='+uid});return}try{await post('notify/read.php',{id:n.id});n.is_read=true;if(n.from_idtype==='tid')uni.navigateTo({url:'/pages/thread/detail?tid='+n.from_id})}catch(e){error.value=e.message}}
function clearRead(){uni.showModal({title:'清理已读通知',content:'将已读通知移入 APP 隐藏列表？论坛记录会保留。',success:async r=>{if(r.confirm){try{await post('notify/clear.php',{});reset()}catch(e){error.value=e.message}}}})}
onLoad(async o=>{if(o.fid){fid.value=Number(o.fid)||0;forumName.value='版块帖子'}reset();try{config.value=await request('app/config.php')}catch{}});onShow(async()=>{try{await account.refresh();unread.value=Number(account.user?.newpm||0)+Number(account.user?.newprompt||0);if(['mine','notify'].includes(tab.value))reset()}catch(e){error.value=e.message}});onPullDownRefresh(reset);onReachBottom(()=>{if(hasMore.value)load()})
</script>
<style scoped>.screen{padding:0 20px 130px}.nav{padding:calc(env(safe-area-inset-top) + 28px) 0 18px;position:sticky;top:0;background:var(--bg);z-index:2}.heading{font-size:34px;font-weight:800;margin:6px 0}.tabs{position:fixed;bottom:calc(env(safe-area-inset-bottom) + 14px);left:14px;right:14px;display:flex;background:var(--card);opacity:.97;backdrop-filter:blur(25px);border:1px solid var(--line);border-radius:26px;padding:12px 0;z-index:5;box-shadow:0 6px 30px #0001}.tab{flex:1;text-align:center;font-size:11px;color:var(--muted)}.active,.selected{color:#007aff}.icon{font-size:25px;height:32px;position:relative}.badge{position:absolute;right:5px;top:-4px;background:#ff3b30;color:#fff;border-radius:10px;padding:1px 4px;font-size:10px}.shortcuts,.segments{display:flex;gap:18px;flex-wrap:wrap;margin:18px 0;font-size:13px}.shortcuts view{background:var(--card);padding:12px;border-radius:16px;color:#007aff}.publish{margin:18px 0}.search{display:flex;gap:10px;margin-bottom:18px}.search input{flex:1;min-width:0}.search button{margin:0;font-size:13px}.avatar{width:66px;height:66px;border-radius:50%;margin-bottom:15px}.stats{margin-top:16px;color:#5856d6}.menu{padding:18px 0;border-bottom:1px solid var(--line)}.menu:last-child{border:0}.dot{color:#ff3b30;font-size:10px}.history{display:flex;gap:12px;flex-wrap:wrap;margin:20px 0}.history text{padding:7px 12px;border-radius:16px;background:var(--bg)}.section{padding:20px 4px 4px;color:var(--muted)}</style>
